package net.civeira.phylax.feature.observe.observedissue.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssue;
import net.civeira.phylax.feature.observe.observedissue.domain.valueobject.TenantsVO;

class TenantsValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of tenants of observed issue")
  void test_tenants_value_holder_assign_plain_value() {
    Object holder = new Object();
    TenantsValueHolder<Object> value = new TenantsValueHolder<>(holder);
    Assertions.assertSame(holder, value.tenants(1), "Setters must return the holder");
    Assertions.assertTrue(value.getTenantsValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals(1, value.getTenants().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of tenants of observed issue")
  void test_tenants_value_holder_assign_value_object() {
    Object holder = new Object();
    TenantsValueHolder<Object> value = new TenantsValueHolder<>(holder);
    TenantsVO vo = TenantsVO.from(1);
    Assertions.assertFalse(value.getTenantsValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.tenants(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getTenantsValue().orElseThrow());
    Assertions.assertSame(holder, value.tenants(Optional.empty()));
    Assertions.assertFalse(value.getTenantsValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.tenants(Optional.of(vo)));
    Assertions.assertSame(vo, value.getTenantsValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of tenants of observed issue against the original")
  void test_tenants_value_holder_read() {
    Object holder = new Object();
    TenantsValueHolder<Object> value = new TenantsValueHolder<>(holder);
    TenantsVO vo = TenantsVO.from(1);
    TenantsVO other = TenantsVO.from(1);
    ObservedIssue original = Mockito.mock(ObservedIssue.class);
    Mockito.when(original.getTenantsValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readTenants(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readTenants(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.tenants(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readTenants(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readTenants(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of tenants of observed issue")
  void test_tenants_value_holder_unset() {
    Object holder = new Object();
    TenantsValueHolder<Object> value = new TenantsValueHolder<>(holder);
    TenantsVO vo = TenantsVO.from(1);
    value.tenants(vo);
    Assertions.assertSame(holder, value.unsetTenantsIfMatches("tenants_other"));
    Assertions.assertTrue(value.getTenantsValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetTenantsIfMatches("tenants"));
    Assertions.assertFalse(value.getTenantsValue().isPresent(),
        "The field name must clear the value");
    value.tenants(vo);
    Assertions.assertSame(holder, value.unsetTenants());
    Assertions.assertFalse(value.getTenantsValue().isPresent(), "Unset must clear the value");
  }
}
